    '[aria-label*="Detener" i]',
    '[aria-label*="Arrêter" i]',
    '[title*="Stop" i]',
    '[title*="Останов" i]',
    '[title*="Detener" i]',
    '[title*="Arrêter" i]',
    'button[data-testid*="stop" i]',
    '[aria-busy="true"]',
    '[data-loading="true"]',
    '[class*="loading" i]',
    '[class*="spinner" i]',
